				policiesRouter.Post("/status", func(w http.ResponseWriter, r *http.Request) {

				})

				policiesRouter.Get("/status/{requestID}", func(w http.ResponseWriter, r *http.Request) {

				})

				policiesRouter.Route("/{policyID}", func(policyRouter chi.Router) {
					// changed to POST /sync from PUT / as it's only requested manually via API
					policyRouter.Post("/sync", func(w http.ResponseWriter, r *http.Request) {})
					policyRouter.Delete("/", func(w http.ResponseWriter, r *http.Request) {})
					policyRouter.Get("/", func(w http.ResponseWriter, r *http.Request) {})
					policyRouter.Get("/status", func(w http.ResponseWriter, r *http.Request) {})
				})
			})
		})

		rr.Route("/v1", func(v1Router chi.Router) {
			v1Router.Route("/markets/{market}", func(marketsRouter chi.Router) {
			})
		})
	})

