		},
	)

cqrs.NewEventBusWithConfig(
		publisher,
		cqrs.EventBusConfig{
			OnPublish: func(params cqrs.OnEventSendParams) error {
				watermillLogger.Info("Publishing event", watermill.LogFields{
					"event_name": params.EventName,
				})

				params.Message.Metadata.Set("published_at", time.Now().String())
				return nil
			},
			GeneratePublishTopic: func(params cqrs.GenerateEventPublishTopicParams) (string, error) {
				return params.EventName, nil
			},
			Marshaler: cqrs.JSONMarshaler{},
			Logger:    watermillLogger,
		},
	)

cqrs.NewEventGroupProcessorWithConfig(
		router,
		cqrs.EventGroupProcessorConfig{
			GenerateSubscribeTopic: func(
				params cqrs.EventGroupProcessorGenerateSubscribeTopicParams,
			) (string, error) {
				return params.EventGroupName, nil
			},
			SubscriberConstructor: func(
				params cqrs.EventGroupProcessorSubscriberConstructorParams,
			) (message.Subscriber, error) {
				return subscriber, nil
			},

			OnHandle: func(params cqrs.EventGroupProcessorOnHandleParams) error {
				start := time.Now()

				err := params.Handler.Handle(params.Message.Context(), params.Event)

				watermillLogger.Info("Event handled", watermill.LogFields{
					"event_name": params.EventName,
					"duration":   time.Since(start),
					"err":        err,
				})

				return err
			},

			Marshaler: cqrs.JSONMarshaler{},
			Logger:    watermillLogger,
		},
	)

